<script setup lang="ts">
import { RefreshCw, Clock3, Play } from '@lucide/vue'
import { clone, state, refresh, perform, runSource, saveConfiguration } from '../../app/state'
import type { Source } from '../../app/types'
import { time } from '../../app/format'
async function toggle(source: Source) { if(!state.config)return;const config=clone(state.config.config);const item=config.sources.find(s=>s.id===source.id)!;item.schedule.enabled=!item.schedule.enabled;await saveConfiguration(config) }
async function cron(source: Source,event: Event) { const value=(event.target as HTMLInputElement).value;if(value===source.schedule.cron)return;if(!state.config)return;const config=clone(state.config.config);config.sources.find(s=>s.id===source.id)!.schedule.cron=value;await saveConfiguration(config) }
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">AUTOMATION</span><h1>计划管理<span>.</span></h1><p>按程序启动时区运行。错过的计划不补跑，重叠任务自动跳过。</p></div><button class="button" @click="perform(refresh)"><RefreshCw :size="16"/>刷新</button></div><div class="panel"><div class="panel-caption"><Clock3 :size="18"/><span>调度时区：{{state.info?.timezone==='Local'?'程序本地时区':state.info?.timezone}}</span><small>五字段 cron · 分 时 日 月 周</small></div><div class="table-scroll"><table><thead><tr><th>同步源</th><th>cron 表达式</th><th>下次运行</th><th>自动计划</th><th class="right">操作</th></tr></thead><tbody><tr v-for="source in state.config?.config.sources" :key="source.id"><td><strong>{{source.name}}</strong><small>{{source.type}}</small></td><td><input class="cron-input" :value="source.schedule.cron" aria-label="cron 表达式" @change="perform(()=>cron(source,$event))"/></td><td>{{source.enabled&&source.schedule.enabled?time(state.info?.schedules[source.id]):'未启用'}}</td><td><button class="toggle" :class="{on:source.schedule.enabled}" :aria-pressed="source.schedule.enabled" :aria-label="'自动计划 '+source.name" @click="perform(()=>toggle(source))"><span></span></button><small v-if="!source.enabled" class="error-text">同步源已禁用</small></td><td class="right"><button class="button compact" :disabled="!source.enabled" @click="perform(()=>runSource(source.id))"><Play :size="14"/>立即同步</button></td></tr><tr v-if="!state.config?.config.sources.length"><td colspan="5" class="empty-state"><Clock3 :size="32"/><h3>暂无运行计划</h3><p>先在同步源页面新增来源。</p></td></tr></tbody></table></div></div></section></template>
